t.script:
(function(){
  var RPC = 'https://ocr-pesee-webhook.onrender.com/heures/rpc';
  var DC = , TOK = '';
  function decide(dec){
    document.getElementById('cdOk').disabled = true;
    document.getElementById('cdKo').disabled = true;
    fetch(RPC, {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({action_id: 2069, ctx: {active_model:'x_demande_conge', dc_id: DC, dc_token: TOK, dc_decision: dec, dc_reponse: document.getElementById('cdCom').value || ''}})
    }).then(function(r){ return r.json(); }).then(function(d){
      if(d.error){ alert('Échec : ' + d.error.message); document.getElementById('cdOk').disabled = false; document.getElementById('cdKo').disabled = false; return; }
      location.reload();
    }).catch(function(){ alert('Échec réseau'); document.getElementById('cdOk').disabled = false; document.getElementById('cdKo').disabled = false; });
  }
  document.getElementById('cdOk').addEventListener('click', function(){ decide('approuve'); });
  document.getElementById('cdKo').addEventListener('click', function(){ decide('refuse'); });
  var d0 = '';
  if(d0 === 'refuse'){ document.getElementById('cdKo').style.outline = '3px solid #7f1d1d'; }
  if(d0 === 'approuve'){ document.getElementById('cdOk').style.outline = '3px solid #14532d'; }
})();
